/*["none","square","circle","pulsating-square","pulsating-circle"]*/

body { background-color: rgba(0, 0, 0, 255); margin: 0px auto; overflow: hidden; 
--slides-studio-refresh: 1;
}

.square {
        position: absolute;
        left: 50%;
        top: 50%;
        transform: translateX(-50%) translateY(-50%);
        border-radius: 0%;
        width: 60%;
        height: 100%;
        background-color: rgb(255, 255, 255);
        }

.circle {
        position: absolute;
        left: 50%;
        top: 50%;
        transform: translateX(-50%) translateY(-50%);
        border-radius: 50%;
        width: 60%;
        height: 100%;
        background-color: rgb(255, 255, 255);
        }

.pulsating-square {
        position: absolute;
        left: 50%;
        top: 50%;
        transform: translateX(-50%) translateY(-50%);
        border-radius: 0%;
        width: 60%;
        height: 100%;

        &:after {
            content: '';
            position: absolute;
            left: 0; 
            top: 0;
            display: block;
            width: 100%;
            height: 100%;
            background-color: rgb(255, 255, 255);
            border-radius: 0%;
            box-shadow: 0 0 8px rgba(0,0,0,1.3);
            animation: pulse-dot 5.25s cubic-bezier(0.455, 0.03, 0.515, 0.955) -.4s 		            infinite;
        }
        }

.pulsating-circle {
        position: absolute;
        left: 50%;
        top: 50%;
        transform: translateX(-50%) translateY(-50%);
        border-radius: 50%;
        width: 60%;
        height: 100%;

        &:after {
            content: '';
            position: absolute;
            left: 0; 
            top: 0;
            display: block;
            width: 100%;
            height: 100%;
            background-color: rgb(255, 255, 255);
            border-radius: 50%;
            box-shadow: 0 0 8px rgba(0,0,0,1.3);
            animation: pulse-dot 5.25s cubic-bezier(0.455, 0.03, 0.515, 0.955) -.4s infinite;
        }
        }


        @keyframes pulse-dot {
        0% {
            transform: scale(.8);
        }
        50% {
            transform: scale(1);
        }
        100% {
            transform: scale(.8);
        }
        }

/*["full-screen","side-by-side","over-the-shoulder"]*/

body { background-color: rgba(0, 0, 0, 0); margin: 0px auto; overflow: hidden; 
--slides-studio-refresh: 1;
}

.full-screen {
    position: absolute;
    top: 0;
    left: 0;
    bottom: 0;
    right: 0;
    width: 100%;
    height: 100%;
    borderStyle: solid;
    borderWidth: 0px;
    borderRadius: 24px;
    transformPerspective: 0;
    transformRotateY: 0deg;
    filterOpacity: 100%; 
    filterDropShadowColor: rgba(0, 0, 0, 50.5);
    filterDropShadowOffsetX: 30px;
    filterDropShadowOffsetY: 21px;
    filterDropShadowBlur: 40px;
}

.side-by-side{
    position: absolute;
    top: 0;
    left: 0;
    bottom: 0;
    right: 0;
    width: 50%;
    height: 100%;
    border-style: solid;
    border-width: 0px;
    border-radius: 24px;
    transform-perspective: 0;
    transform-rotate-y: 0deg;
    filterOpacity: 100%; 
    filterDropShadowColor: rgba(0, 0, 0, 50.5);
    filterDropShadowOffsetX: 30px;
    filterDropShadowOffsetY: 21px;
    filterDropShadowBlur: 40px;
}

.over-the-shoulder{
    position: absolute;
    top: 10%;
    left: 10%;
    bottom: 0;
    right: 0;
    width: 25%;
    height: 40%;
    border-style: solid;
    border-width: 0px;
    border-radius: 24px;
    transform: perspective(1500px) rotateY(15deg); 
    filter: opacity(100%); 
    filter: drop-shadow(30px 21px 40px rgba(0, 0, 0, 50.5));
            transition:
                width 0.5s, 
                height 0.5s,
                top 0.5s,
                left 0.5s,
                bottom 0.5s,
                right 0.5s,
                border-radius 0.5s,
                filter 0.5s;
}
